-- protos[107] = updateParticles107   (named by lifter, 21 lines)
--==========================================================================
do
local function updateParticles107(upvalues, particles, deltaTime, update, render)
  local index = #particles
  while index >= 1 do
    local particle = particles[index]
    particle.age = particle.age + deltaTime
    if particle.age >= particle.life then
      local dispose = cell_get(upvalues[1])
      dispose(particle)
      local remove = table.remove
      remove(particles, index)
    else
      update(particle, deltaTime)
      render(particle)
    end
    index -= 1
  end
end
protos[107] = updateParticles107
end

