-- protos[1981] = parseKeyBinding   (named by lifter, 29 lines)
--   strings: "", "Alt+", "Ctrl+", "None", "Shift+"
--==========================================================================
do
local function parseKeyBinding(upvalues, binding)
  if not binding or binding == "" or binding == "None" then return nil end
  local key = binding
  local ctrl, shift, alt = false, false, false
  while true do
    if key:sub(1, 5) == "Ctrl+" then
      ctrl = true
      key = key:sub(6)
    elseif key:sub(1, 6) == "Shift+" then
      shift = true
      key = key:sub(7)
    elseif key:sub(1, 4) == "Alt+" then
      alt = true
      key = key:sub(5)
    else
      break
    end
  end
  local result = new_table(0)
  result.key = key
  result.ctrl = ctrl
  result.shift = shift
  result.alt = alt
  return result
end
protos[1981] = parseKeyBinding
end

