-- protos[1999] = waitForTruthyResult   (named by lifter, 18 lines)
--==========================================================================
do
local function waitForTruthyResult(upvalues, predicate, timeout)
  local now = os.clock()
  local duration = timeout
  if not timeout then duration = 1 end
  local deadline = now + duration
  while true do
    local ok, result = pcall(predicate)
    if ok and result then return result end
    local wait = task.wait
    wait(0.05)
    if os.clock() > deadline then return nil end
  end
end
protos[1999] = waitForTruthyResult
